head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. tabControl안에 trigger버튼 및 inputbox버튼의 disabled="true"로 설정한다.
    //1. Set the trigger and inputbox buttons in tabControl to disabled = "true".
    //Verify 1. tabControl안에 trigger버튼 및 inputbox버튼의 disabled="true"로 설정된다.
    //1. In the tabControl, the trigger and inputbox buttons are set to disabled = "true".
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('trigger2').getAttribute('disabled')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getAttribute('disabled')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 이벤트버튼(tab.enableTab)을 클릭하여 tab의 disable을 해제한다.(tabControl1.enableTab(0);)-Click on the event button (tab.enableTab) to disable the tab. (TabControl1.enableTab0);)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. tabControl 내부의 disable로 처리된 trigger버튼및 inputbox는 disable을 유지한다.(이전에는 enable처리됨)-Disable trigger buttons and inputboxes that are disabled in the tabControl (previously enabled)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('trigger2').getAttribute('disabled')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getAttribute('disabled')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create by Truong.Luu
    //Create date 19-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
